quotes.text:
p.center {
	text-align: center;
	color: red;
}

p.large {
	font-size: 300%
;}

* [lang^="en"] {
	color: green;
}

*.warning {
	color: red;
}

*#maincontent {
	border: 1px solid blue;
}

.floating {
	float: left;
}

/* automatically clear the next sibling after a floating element */
.floating + * {
	clear: left;
}

img.one {
	height: auto;
}

img.two {
	height: 200px;
	width: 200px;
}

div.three {
	height: 300px;
	width: 300px;
	background-color: powderblue;
}

.form {
	display: flex;
	flex-direction: column;
	justify-content: flex-start;
	margin: 80px auto;
	font-size: 20px;
	width: 75%;
	border-radius: 10px;
	box-shadow: 0 4px 8px rgb(0, 0, 0, 0.4);
	box-sizing: border-box;
}

.button {
	background-color: #007bff;
	color: #ffffff;
	padding: 10px 20px;
	border: none;
	border-radius: 5px;
	cursor: pointer;
	transition: background-color 0.3s, color 0.3s;
}

.button:hover {
	background-color: #0056b3;
	color: #ffffff;
}

body {
	background-color: #f0f0f0;
}

@media (max-width: 600px) {
	body {
		background-color: #e6f7ff;
	}
}

@media (min-width: 601px) and (max-width: 992px) {
	body {
		background-color: #f9f6ff;
	}
}

@media (min-width: 993px) {
	body {
		background-color: #f2f2f2;
	}
}

.grid-container {
	display: grid;
	grid-template-columns: 1fr 1fr 1fr;
	grid-gap: 10px;
}

.grid-item {
	background-color: #f0f0f0;
	padding: 20px;
	text-align: center;	}

.wrapper {
	border: 2px dotted rgb(96, 139, 168);
	width: 500px;
}

.box {
	display: flex;
	flex-wrap: wrap;
	gap: 10px;
}

.box>* {
	flex: 1 1 160px;
}

.center {
	height: 200px;
	position: relative;
	border: 3px solid green;
}

.center p {
	margin: 0;
	position: absolute;
	top: 50%;
	left: 50%;
	-ms-transform: translate(-50%, -50%);
	transform: translate(-50%, -50%);
}

input[type=button], input[type=submit], input[type=reset] {
	background-color: #04AA6D;
	border: none;
	color: white;
	padding: 16px 32px;
	text-decoration: none;
	margin: 4px 2px;
	cursor: pointer;
}

@keyframes slide {
	0% { margin-left: 0; }
	50% { margin-left: 200px; }
	100% { margin-left: 0; }
}

.slide-div {
	width: 200px;
	height: 100px;
	background-color: lightgreen;
	animation: slide 3s infinite;
}

/* General body styles */
body {
	font-family: Arial, sans-serif;
	margin: 0;
	padding: 0;
	background-color: #f4f4f4;
	color: #333;
}
